// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testRegression_property() public {
        Reverter reverter = new Reverter();

        vm.deal(address(this), 1 ether);
        (bool success,) = address(c).call{value: 1 ether}("");
        assertTrue(success);

        bool ok;
        try c.sendMoney(address(reverter), 0.5 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == true);
    }
}

contract Reverter {
    receive() external payable {
        revert("I reject ether");
    }
}
